create table public.suppliers(id uuid primary key default gen_random_uuid(),name text not null,phone text,address text,created_at timestamptz not null default now());
create table public.purchase_invoices(id uuid primary key default gen_random_uuid(),supplier_id uuid references public.suppliers(id),invoice_reference text,subtotal numeric(12,2) not null default 0,paid numeric(12,2) not null default 0,due numeric(12,2) not null default 0,status text not null default 'draft',created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.purchase_items(id uuid primary key default gen_random_uuid(),purchase_id uuid not null references public.purchase_invoices(id),variant_id uuid not null references public.product_variants(id),quantity integer not null check(quantity>0),unit_cost numeric(12,2) not null check(unit_cost>=0));
create table public.stocktakes(id uuid primary key default gen_random_uuid(),status text not null default 'draft' check(status in('draft','submitted','approved','rejected')),notes text,created_by uuid references public.profiles(id),approved_by uuid references public.profiles(id),created_at timestamptz not null default now(),approved_at timestamptz);
create table public.stocktake_items(id uuid primary key default gen_random_uuid(),stocktake_id uuid not null references public.stocktakes(id),variant_id uuid not null references public.product_variants(id),system_quantity integer not null,actual_quantity integer not null,reason text);
create table public.exchanges(id uuid primary key default gen_random_uuid(),original_sale_id uuid not null references public.sales(id),created_by uuid references public.profiles(id),reason text not null,status text not null default 'pending',price_difference numeric(12,2) not null default 0,created_at timestamptz not null default now());
create table public.exchange_items(id uuid primary key default gen_random_uuid(),exchange_id uuid not null references public.exchanges(id),returned_variant_id uuid not null references public.product_variants(id),replacement_variant_id uuid references public.product_variants(id),quantity integer not null check(quantity>0));
create table public.expenses(id uuid primary key default gen_random_uuid(),category text not null,description text not null,amount numeric(12,2) not null check(amount>0),payment_method public.payment_method not null default 'cash',created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.cash_sessions(id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.profiles(id),opening_cash numeric(12,2) not null default 0,expected_cash numeric(12,2),counted_cash numeric(12,2),variance numeric(12,2),status text not null default 'open' check(status in('open','closed')),opened_at timestamptz not null default now(),closed_at timestamptz);
create table public.store_settings(id integer primary key default 1 check(id=1),store_name text not null default 'BARTIKA JEANS',store_name_ar text not null default 'بارتيكا جينز',phone text,address text,logo_url text,quick_discount_percent numeric(5,2) not null default 20 check(quick_discount_percent between 0 and 20),exchange_days integer not null default 3);
alter table public.suppliers enable row level security;alter table public.purchase_invoices enable row level security;alter table public.purchase_items enable row level security;alter table public.stocktakes enable row level security;alter table public.stocktake_items enable row level security;alter table public.exchanges enable row level security;alter table public.exchange_items enable row level security;alter table public.expenses enable row level security;alter table public.cash_sessions enable row level security;alter table public.store_settings enable row level security;
create policy "admin suppliers" on public.suppliers for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "admin purchases" on public.purchase_invoices for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "admin purchase items" on public.purchase_items for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "admin stocktakes" on public.stocktakes for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "admin stocktake items" on public.stocktake_items for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "admin exchanges" on public.exchanges for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "admin exchange items" on public.exchange_items for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "admin expenses" on public.expenses for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "cash own or admin" on public.cash_sessions for select to authenticated using(public.is_admin() or seller_id=auth.uid());create policy "cash admin manage" on public.cash_sessions for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "settings read" on public.store_settings for select to authenticated using(true);create policy "settings admin" on public.store_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
grant select,insert,update,delete on public.suppliers,public.purchase_invoices,public.purchase_items,public.stocktakes,public.stocktake_items,public.exchanges,public.exchange_items,public.expenses,public.cash_sessions,public.store_settings to authenticated;
insert into public.store_settings(id) values(1) on conflict do nothing;